CREATE TABLE IF NOT EXISTS system_manuals ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id TEXT NOT NULL DEFAULT 'giyeun', menu_id TEXT NOT NULL, manual_url TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()), updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()), UNIQUE(tenant_id, menu_id) ); ALTER TABLE system_manuals ENABLE ROW LEVEL SECURITY; CREATE POLICY "allow_anon_all" ON system_manuals FOR ALL TO anon USING (true) WITH CHECK (true); CREATE POLICY "allow_auth_all" ON system_manuals FOR ALL TO authenticated USING (true) WITH CHECK (true);
